		padding: 1.7rem;
    display: flex;
    align-items: center;
    border: .1rem solid #E0E0E0;
    border-top: 0;
}
.a-nha-cai.first-item{
		border-top: .1rem solid #E0E0E0;
		border-radius: 10px 10px 0 0;
}
.a-nha-cai.last-item{
	border-radius: 0 0 10px 10px;
}
.a-nha-cai .box-text-inner{
		display: flex;
}
.a-nha-cai .stack{
		gap: 7px;
}

.a-nha-cai .box-image{
	max-width: 140px;
}

.a-nha-cai .box-text-inner .a-text .a-label{
	  font-size: 14px;
    font-weight: 700;
    text-transform: uppercase;
    color: #FB6107;
    background-color: #FFE3CD;
    border-radius: 4px 4px 4px 4px;
    padding: 4px 7px;
}

.a-nha-cai .box-text-inner .a-text .text1{
	  font-size: 16px;
    font-weight: 700;
    color: #393939;
}

.card-nc2 .box-image,
.card-nc1 .box-image{
		position: relative;
    max-width: 200px;
    margin: 0;
    padding-top: 25px;
		margin-right: 10px;
}

.card-nc1 .abs-stack{
	  max-width: 185px;
    background: #fff;
	  gap: 7px;
    padding-top: 25px;
		border-radius: 0 0 10px 10px;
    position: absolute;
    top: 0;
    left: 70%;
}

.card-nc1 .abs-stack .button{
	  width: 100%;
    border-radius: 0 0 10px 10px;
}

.card-nc1 .first-item p{
	  font-size: 16px;
    font-weight: 700;
    text-transform: uppercase;
    line-height: 16px;
    color: #595959!important;
}

.card-nc1 .last-item .bg{
	  font-size: 48px;
    font-weight: 700;
    text-transform: none;
    line-height: 35px;
    color: var(--fs-color-primary);
}

.card-nc1 .last-item .sm{
	  font-size: 24px;
    font-weight: 500;
    text-transform: none;
    line-height: 36px;
    color: #8C8C8C!important;
}

.card-nc1 >.col-inner{
	border-radius: 10px 10px 0 0;
}
.card-nc2 >.col-inner{
	border-radius: 0 0 10px 10px;	
}

.card-nc2 .no-pd .box-image{
	padding: 0;
}

.card-nc2 .button.white{
	white-space: nowrap;
}

.mw-200,
.box-style1 .box-image{
	max-width: 200px
}

.rate-box p{
	   margin-bottom: 10px;
    display: flex;
    justify-content: space-between;
		align-items: center;
}

.rate-box p .score{
	  padding: .2rem;
    border-radius: .4rem;
    background-color: #FFE3CD;
    color: #FB6107;
    font-weight: 700;
}

.large-3 .ez-toc-heading-1{
	display: none !important;
}

.large-3 .ez-toc-list-level-2{
	margin-left: 0 !important;
}

.col-inner:has(.a-sidebar-2) {
    top: -800px;
}

.mb-10{
	margin-bottom: 10px;
}
.mb-15{
	margin-bottom: 15px
}

.card3-nhacai{
	  border: 1px solid;
    border-radius: 10px;
    margin: 15px 0;
}

.bg-head1 >.col-inner{
	  background-image: url(/wp-content/uploads/2025/06/bg-head1.webp);
    background-size: cover;
    border-radius: 10px 10px 0 0;
}

.task-progress p {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 15px;
    font-weight: 700;
    margin-bottom: 0;
}

.progress {
    width: 100%;
    -webkit-appearance: none;
    appearance: none;
    border: none;
    border-radius: 100%;
    height: 8px;
    transition: value 1s ease;
}

.progress::-webkit-progress-bar {
    background-color: #f0f0f0;
		border: 1px solid #000;
}

.progress::-webkit-progress-bar,
.progress::-webkit-progress-value {
    border-radius: 10px;
    transition: width 1s ease;
}

.progress::-moz-progress-bar {
    border-radius: 10px;
}

.progress1::-webkit-progress-value {
    background: #FB6107;
}

.task-progress{
    margin-bottom: 20px;
}

.progress-cont{
	   display: flex;
    align-items: center;
    gap: 8px;
}

.progress-cont .score{
	  font-size: 26px;
    font-weight: 700;
    text-transform: uppercase;
    line-height: 30px;
    letter-spacing: 0.9px;
    color: #FB6107;
    border-radius: 7px 7px 7px 7px;
    background-color: #FFE3CD;
    padding: 5px;
    transform: translateY(-15px);
}

.sm-progress .progress-cont .score{
	  font-size: 16px;
    transform: translateY(-12px);
		line-height: unset;
}

@media only screen and (max-width : 550px) {
	.a-nha-cai .box-text-inner{
			flex-wrap: wrap;
			gap: 5px;
	}

	.card-nc1 >.col-inner{
		display: flex;
	}

	.card-nc1 .abs-stack{
			position: relative;
			width: 100%;
			top: 10px;
			left: 0;
			margin-bottom: 24px;
	}

}</style><style id="kirki-inline-styles"></style></head><body class="error404 wp-theme-flatsome wp-child-theme-flatsome-child header-shadow lightbox nav-dropdown-has-arrow nav-dropdown-has-shadow nav-dropdown-has-border"><img data-lazyloaded="1" src="data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI4MDAiIGhlaWdodD0iNDAwIiB2aWV3Qm94PSIwIDAgODAwIDQwMCI+PHJlY3Qgd2lkdGg9IjEwMCUiIGhlaWdodD0iMTAwJSIgc3R5bGU9ImZpbGw6I2NmZDRkYjtmaWxsLW9wYWNpdHk6IDAuMTsiLz48L3N2Zz4=" width="800" height="400" fetchpriority="high" style="width: 100%;height: 300px;position: absolute;top: 0;left: 0;z-index: -1"
